<script setup>
import { computed, ref } from 'vue'; import CircuitScene from './components/CircuitScene.vue'; import ComponentLibrary from './components/ComponentLibrary.vue'; import SchematicView from './components/SchematicView.vue';
const view=ref('3d'), simState=ref('normal'), selected=ref(null), placed=ref(['battery','resistor','led']); const status=computed(()=>({normal:{label:'FUNCIONANDO',tone:'ok',detail:'Corriente dentro del margen seguro'},overload:{label:'SOBRECORRIENTE',tone:'warn',detail:'La resistencia supera su potencia nominal'},short:{label:'CORTOCIRCUITO',tone:'danger',detail:'La corriente sube y el componente se quema'}}[simState.value])); function add(c){placed.value.push(c.id);selected.value=c}
</script>
<template><main class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">⌁</div><div><span class="eyebrow">Electronics playground</span><h1>CircuitForge Lab</h1><p>Laboratorio 3D para aprender electrónica.</p></div></div><div class="simulation-actions"><button class="button" :class="{active:simState==='normal'}" @click="simState='normal'">▶ Funciona</button><button class="button" :class="{active:simState==='overload'}" @click="simState='overload'">⚡ Sobrecarga</button><button class="button danger-button" :class="{active:simState==='short'}" @click="simState='short'">✹ Cortocircuito</button></div></header><section class="editor card"><ComponentLibrary :selected-id="selected?.id" @select="selected=$event" @add="add"/><section class="editor-stage"><div class="stage-toolbar"><div><span class="eyebrow">Editor interactivo</span><h2>{{view==='3d'?'Protoboard 3D':'Diagrama eléctrico'}}</h2><p class="stage-detail">{{status.detail}}</p></div><div class="view-switch"><button class="mini-button" :class="{active:view==='3d'}" @click="view='3d'">3D</button><button class="mini-button" :class="{active:view==='diagram'}" @click="view='diagram'">Esquema</button></div></div><div class="stage-board" :class="`state-${status.tone}`"><CircuitScene v-if="view==='3d'"/><SchematicView v-else/><div class="simulation-banner" :class="status.tone"><strong>{{status.label}}</strong><span>{{status.detail}}</span></div><div class="placed-components"><button v-for="(id,i) in placed" :key="`${id}-${i}`" class="placed-chip">{{id.toUpperCase()}} #{{i+1}}</button></div></div></section><aside class="inspector"><span class="eyebrow">Inspector</span><h3>{{selected?.name||'Selecciona un componente'}}</h3><p>{{selected?.description||'Añade un componente desde la biblioteca para ver pines, valor y estado.'}}</p><dl v-if="selected"><div><dt>Valor</dt><dd>{{selected.value}}</dd></div><div><dt>Pines</dt><dd>{{selected.pins.join(' · ')}}</dd></div><div><dt>Simulación</dt><dd>{{status.label}}</dd></div></dl></aside></section><section class="card education-note"><span class="eyebrow">Aprende con seguridad</span><h2>Observa qué ocurre cuando el circuito está bien o falla.</h2><p>En modo sobrecarga se supera la potencia de la resistencia; en cortocircuito se representa una corriente peligrosa y el componente se marca como quemado. Es una explicación visual, no una instrucción para probar fallos con hardware real.</p></section><footer>Construido con Vue, Vite y Three.js · <a href="https://github.com/uppy19d0/circuitforge-lab" target="_blank">Repositorio en GitHub</a></footer></main></template>
